#!/usr/bin/env bash
set -euo pipefail
cd /workspaces/jadrix
mkdir -p public src data
cat > public/index.html <<'HTML'
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jadrix ERP</title><style>
:root{--bg:#0f172a;--panel:#172033;--panel2:#1e293b;--line:#334155;--text:#e5e7eb;--muted:#94a3b8;--accent:#22c55e;--accent2:#38bdf8;--danger:#ef4444}*{box-sizing:border-box}body{margin:0;font-family:Tahoma,Arial,sans-serif;background:var(--bg);color:var(--text)}button,input,select{font:inherit}.top{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;background:#111827;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}.brand{font-weight:700;font-size:22px}.badge{background:#14532d;color:#bbf7d0;padding:6px 10px;border-radius:999px;font-size:12px}.layout{display:grid;grid-template-columns:240px 1fr;min-height:calc(100vh - 58px)}aside{background:#111827;border-left:1px solid var(--line);padding:14px}.navbtn{width:100%;text-align:right;margin:5px 0;padding:11px;border:1px solid transparent;border-radius:10px;background:transparent;color:var(--text);cursor:pointer}.navbtn.active,.navbtn:hover{background:var(--panel2);border-color:var(--line)}main{padding:18px}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px}.card h3{margin:0 0 8px;color:var(--accent2)}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.btn{border:0;border-radius:9px;padding:9px 12px;background:#334155;color:white;cursor:pointer}.btn.primary{background:var(--accent);color:#052e16;font-weight:700}.btn.danger{background:var(--danger)}input,select{background:#0b1220;color:white;border:1px solid var(--line);border-radius:8px;padding:9px;width:100%}.row{display:grid;grid-template-columns:repeat(12,1fr);gap:8px;margin-bottom:8px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c6{grid-column:span 6}.c8{grid-column:span 8}.table{width:100%;border-collapse:collapse;background:var(--panel)}.table th,.table td{border-bottom:1px solid var(--line);padding:9px;text-align:right}.table th{color:#bae6fd}.tree{background:#0b1220;border:1px solid var(--line);border-radius:12px;padding:10px;max-height:62vh;overflow:auto}.node{padding:7px;border-radius:7px;cursor:pointer}.node:hover{background:#1f2937}.lvl1{font-weight:700;color:#fde047}.indent{display:inline-block}.split{display:grid;grid-template-columns:1fr 320px;gap:12px}.muted{color:var(--muted);font-size:13px}.ok{color:#86efac}.bad{color:#fca5a5}@media(max-width:800px){.layout{grid-template-columns:1fr}aside{display:flex;overflow:auto;border-left:0;border-bottom:1px solid var(--line)}.navbtn{min-width:150px}.split{grid-template-columns:1fr}.row{grid-template-columns:1fr}.c3,.c4,.c6,.c8{grid-column:span 1}}
</style></head><body><header class="top"><div class="brand">Jadrix ERP</div><div class="badge">نسخة تطوير تشغيلية</div></header><div class="layout"><aside id="nav"><button class="navbtn active" data-view="dashboard">لوحة التحكم</button><button class="navbtn" data-view="accounts">شجرة الحسابات</button><button class="navbtn" data-view="journal">القيود اليومية</button><button class="navbtn" data-view="ledger">دفتر الأستاذ</button><button class="navbtn" data-view="trial">ميزان المراجعة</button></aside><main>
<section id="dashboard" class="view active"><h2>لوحة التحكم المالية</h2><div class="grid"><div class="card"><h3>عدد الحسابات</h3><div id="kpiAccounts">0</div></div><div class="card"><h3>القيود المرحلة</h3><div id="kpiEntries">0</div></div><div class="card"><h3>إجمالي المدين</h3><div id="kpiDebit">0.00</div></div><div class="card"><h3>إجمالي الدائن</h3><div id="kpiCredit">0.00</div></div></div></section>
<section id="accounts" class="view"><h2>شجرة الحسابات</h2><div class="toolbar"><button class="btn primary" onclick="openAccountForm()">حساب جديد</button><input id="accountSearch" style="max-width:280px" placeholder="بحث بالكود أو الاسم" oninput="renderAccounts()"></div><div class="split"><div class="tree" id="accountTree"></div><div class="card"><h3>تفاصيل الحساب</h3><div id="accountDetails" class="muted">اختر حسابًا من الشجرة</div></div></div></section>
<section id="journal" class="view"><h2>قيد يومية</h2><div class="card"><div class="row"><div class="c3"><label>التاريخ</label><input id="jDate" type="date"></div><div class="c6"><label>البيان</label><input id="jMemo" placeholder="وصف القيد"></div><div class="c3"><label>المرجع</label><input id="jRef" placeholder="اختياري"></div></div><table class="table"><thead><tr><th>الحساب</th><th>البيان</th><th>مدين</th><th>دائن</th><th></th></tr></thead><tbody id="jLines"></tbody></table><div class="toolbar" style="margin-top:10px"><button class="btn" onclick="addLine()">إضافة سطر</button><button class="btn primary" onclick="postEntry()">ترحيل القيد</button></div><div id="journalStatus" class="muted"></div></div></section>
<section id="ledger" class="view"><h2>دفتر الأستاذ</h2><div class="toolbar"><select id="ledgerAccount" style="max-width:320px" onchange="renderLedger()"></select></div><table class="table"><thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody id="ledgerBody"></tbody></table></section>
<section id="trial" class="view"><h2>ميزان المراجعة</h2><table class="table"><thead><tr><th>الكود</th><th>الحساب</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody id="trialBody"></tbody></table></section>
</main></div><dialog id="accountDialog" style="background:#172033;color:white;border:1px solid #334155;border-radius:12px;min-width:min(92vw,420px)"><form method="dialog" onsubmit="saveAccount(event)"><h3>إضافة حساب</h3><div class="row"><div class="c4"><input id="aCode" placeholder="الكود" required></div><div class="c8"><input id="aName" placeholder="اسم الحساب" required></div></div><div class="row"><div class="c6"><select id="aParent"></select></div><div class="c6"><select id="aType"><option value="group">تجميعي</option><option value="posting">قابل للقيد</option></select></div></div><div class="toolbar"><button class="btn primary" value="default">حفظ</button><button class="btn" value="cancel">إلغاء</button></div></form></dialog>
<script>
const seedAccounts=[{id:1,code:"1",name:"الأصول",parent:null,type:"group",nature:"debit"},{id:2,code:"2",name:"الخصوم",parent:null,type:"group",nature:"credit"},{id:3,code:"3",name:"حقوق الملكية",parent:null,type:"group",nature:"credit"},{id:4,code:"4",name:"الإيرادات",parent:null,type:"group",nature:"credit"},{id:5,code:"5",name:"المصاريف",parent:null,type:"group",nature:"debit"},{id:11,code:"111",name:"الصندوق",parent:1,type:"posting",nature:"debit"},{id:12,code:"112",name:"البنك",parent:1,type:"posting",nature:"debit"},{id:21,code:"211",name:"الموردون",parent:2,type:"posting",nature:"credit"},{id:31,code:"311",name:"رأس المال",parent:3,type:"posting",nature:"credit"},{id:41,code:"411",name:"إيرادات المبيعات",parent:4,type:"posting",nature:"credit"},{id:51,code:"511",name:"مصروفات تشغيلية",parent:5,type:"posting",nature:"debit"}];let accounts=JSON.parse(localStorage.getItem("jadrix_accounts")||"null")||seedAccounts;let entries=JSON.parse(localStorage.getItem("jadrix_entries")||"[]");const money=n=>Number(n||0).toLocaleString("ar-SA",{minimumFractionDigits:2,maximumFractionDigits:2});function save(){localStorage.setItem("jadrix_accounts",JSON.stringify(accounts));localStorage.setItem("jadrix_entries",JSON.stringify(entries))}document.querySelectorAll(".navbtn").forEach(b=>b.onclick=()=>{document.querySelectorAll(".navbtn").forEach(x=>x.classList.remove("active"));b.classList.add("active");document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));document.getElementById(b.dataset.view).classList.add("active");refreshAll()});function renderAccounts(){const q=(document.getElementById("accountSearch")?.value||"").trim();const out=[];function walk(parent,lvl){accounts.filter(a=>a.parent===parent).sort((a,b)=>a.code.localeCompare(b.code)).forEach(a=>{if(!q||a.code.includes(q)||a.name.includes(q))out.push(`<div class="node ${lvl===1?"lvl1":""}" onclick="showAccount(${a.id})"><span class="indent" style="width:${(lvl-1)*18}px"></span>${a.type==="group"?"📁":"📄"} ${a.code} - ${a.name}</div>`);walk(a.id,lvl+1)})}walk(null,1);document.getElementById("accountTree").innerHTML=out.join("")||'<div class="muted">لا توجد نتائج</div>'}function showAccount(id){const a=accounts.find(x=>x.id===id);document.getElementById("accountDetails").innerHTML=`<b>${a.code} - ${a.name}</b><hr><p>النوع: ${a.type==="group"?"تجميعي":"قابل للقيد"}</p><p>الطبيعة: ${a.nature==="debit"?"مدين":"دائن"}</p><p>الحساب الأب: ${accounts.find(x=>x.id===a.parent)?.name||"—"}</p>`}function openAccountForm(){document.getElementById("aParent").innerHTML='<option value="">بدون حساب أب</option>'+accounts.filter(a=>a.type==="group").map(a=>`<option value="${a.id}">${a.code} - ${a.name}</option>`).join("");document.getElementById("accountDialog").showModal()}function saveAccount(e){e.preventDefault();const code=aCode.value.trim(),name=aName.value.trim();if(accounts.some(a=>a.code===code)){alert("كود الحساب مستخدم");return}const parent=aParent.value?Number(aParent.value):null;const root=parent?accounts.find(a=>a.id===parent):null;accounts.push({id:Date.now(),code,name,parent,type:aType.value,nature:root?.nature||"debit"});save();accountDialog.close();renderAccounts();refreshAll()}function postingAccounts(){return accounts.filter(a=>a.type==="posting")}function addLine(){const tr=document.createElement("tr");tr.innerHTML=`<td><select class="acc">${postingAccounts().map(a=>`<option value="${a.id}">${a.code} - ${a.name}</option>`).join("")}</select></td><td><input class="memo"></td><td><input class="debit" type="number" min="0" step="0.01"></td><td><input class="credit" type="number" min="0" step="0.01"></td><td><button class="btn danger" onclick="this.closest('tr').remove()">×</button></td>`;jLines.appendChild(tr)}function postEntry(){const lines=[...jLines.querySelectorAll("tr")].map(tr=>({accountId:Number(tr.querySelector(".acc").value),memo:tr.querySelector(".memo").value,debit:Number(tr.querySelector(".debit").value||0),credit:Number(tr.querySelector(".credit").value||0)})).filter(l=>l.debit||l.credit);const d=lines.reduce((s,l)=>s+l.debit,0),c=lines.reduce((s,l)=>s+l.credit,0);if(lines.length<2||Math.abs(d-c)>0.005){journalStatus.innerHTML='<span class="bad">القيد غير متوازن أو أقل من سطرين.</span>';return}entries.push({id:Date.now(),date:jDate.value||new Date().toISOString().slice(0,10),memo:jMemo.value,ref:jRef.value||("JE-"+(entries.length+1)),lines});save();journalStatus.innerHTML='<span class="ok">تم ترحيل القيد بنجاح.</span>';jLines.innerHTML="";addLine();addLine();refreshAll()}function balances(){const m={};postingAccounts().forEach(a=>m[a.id]={debit:0,credit:0});entries.forEach(e=>e.lines.forEach(l=>{if(m[l.accountId]){m[l.accountId].debit+=l.debit;m[l.accountId].credit+=l.credit}}));return m}function renderTrial(){const b=balances();trialBody.innerHTML=postingAccounts().map(a=>{const x=b[a.id];return `<tr><td>${a.code}</td><td>${a.name}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td><td>${money(x.debit-x.credit)}</td></tr>`}).join("")}function renderLedgerOptions(){ledgerAccount.innerHTML=postingAccounts().map(a=>`<option value="${a.id}">${a.code} - ${a.name}</option>`).join("");renderLedger()}function renderLedger(){const id=Number(ledgerAccount.value);let bal=0,rows=[];entries.slice().sort((a,b)=>a.date.localeCompare(b.date)).forEach(e=>e.lines.filter(l=>l.accountId===id).forEach(l=>{bal+=l.debit-l.credit;rows.push(`<tr><td>${e.date}</td><td>${e.ref}</td><td>${l.memo||e.memo||""}</td><td>${money(l.debit)}</td><td>${money(l.credit)}</td><td>${money(bal)}</td></tr>`)}));ledgerBody.innerHTML=rows.join("")||'<tr><td colspan="6" class="muted">لا توجد حركة</td></tr>'}function refreshAll(){renderAccounts();renderTrial();renderLedgerOptions();const b=balances();const d=Object.values(b).reduce((s,x)=>s+x.debit,0),c=Object.values(b).reduce((s,x)=>s+x.credit,0);kpiAccounts.textContent=accounts.length;kpiEntries.textContent=entries.length;kpiDebit.textContent=money(d);kpiCredit.textContent=money(c)}jDate.value=new Date().toISOString().slice(0,10);addLine();addLine();refreshAll();
</script></body></html>
HTML
cat > README.md <<'MD'
